import {
    Table,
    MultiLineTextColumn,
    BooleanColumn,
    ReferenceColumn,
    GuidColumn,
    StringColumn,
    FloatColumn,
    DateTimeColumn,
    IntegerColumn,
    GenericColumn,
} from '@servicenow/sdk/core'

export const cmn_location = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        kagami_csindex_enabled: true,
    },
    display: 'name',
    label: 'Location',
    name: 'cmn_location',
    schema: {
        street: MultiLineTextColumn({
            label: 'Street',
            maxLength: 255,
        }),
        stock_room: BooleanColumn({
            default: false,
            label: 'Stock room',
        }),
        life_cycle_stage: ReferenceColumn({
            label: 'Life Cycle Stage',
            maxLength: 40,
            referenceTable: 'life_cycle_stage',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStage()',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        fax_phone: StringColumn({
            label: 'Fax phone',
        }),
        longitude: FloatColumn({
            label: 'Longitude',
            maxLength: 40,
        }),
        primary_location: ReferenceColumn({
            label: [
                {
                    hint: 'Original location this location is duplicating',
                    label: 'Primary location',
                    plural: 'Primary locations',
                    language: 'en',
                },
            ],
            referenceTable: 'cmn_location',
        }),
        country: StringColumn({
            dropdown: 'suggestion',
            label: 'Country',
        }),
        full_name: StringColumn({
            label: [
                {
                    hint: 'System maintained field',
                    label: 'Full name',
                    plural: 'Full names',
                    language: 'en',
                },
            ],
            maxLength: 255,
        }),
        managed_by_group: ReferenceColumn({
            label: [
                {
                    hint: 'User group responsible for managing this location',
                    label: 'Managed by group',
                    plural: 'Managed by groups',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user_group',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        state: StringColumn({
            label: 'State / Province',
        }),
        parent: ReferenceColumn({
            attributes: {
                tree_picker: true,
            },
            cascadeRule: 'restrict',
            label: 'Parent',
            referenceTable: 'cmn_location',
        }),
        cmn_location_type: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Location type',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        coordinates_retrieved_on: DateTimeColumn({
            label: [
                {
                    hint: 'Date and time when the latitide and longitude are populated',
                    label: 'Coordinates retrieved on',
                    plural: 'Coordinates retrieved ons',
                    language: 'en',
                },
            ],
        }),
        phone_territory: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Phone territory',
            referenceTable: 'sys_phone_territory',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        contact: ReferenceColumn({
            dependent: 'company',
            label: 'Contact',
            referenceTable: 'sys_user',
        }),
        lat_long_error: StringColumn({
            label: 'Lat long error',
            maxLength: 1000,
        }),
        phone: StringColumn({
            label: 'Phone',
        }),
        latitude: FloatColumn({
            label: 'Latitude',
            maxLength: 40,
        }),
        duplicate: BooleanColumn({
            label: [
                {
                    hint: 'If true, this location is a duplicate of another existing location record',
                    label: 'Duplicate',
                    plural: 'Duplicates',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        zip: StringColumn({
            label: 'Zip / Postal Code',
        }),
        parent_hp1: GenericColumn({
            attributes: {
                loader_exempt: true,
                serializer: 'com.glide.script.OmittedElementXMLSerializer',
            },
            columnType: 'record_hierarchy_path',
            label: 'Parent HP1',
            maxLength: 255,
            readOnly: true,
        }),
        cmn_location_source: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Discovery source for this location',
                    label: 'Location source',
                    plural: 'Location sources',
                    language: 'en',
                },
            ],
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        city: StringColumn({
            label: 'City',
        }),
        company: ReferenceColumn({
            label: 'Company',
            referenceTable: 'core_company',
        }),
        life_cycle_stage_status: ReferenceColumn({
            label: 'Life Cycle Stage Status',
            maxLength: 40,
            referenceTable: 'life_cycle_stage_status',
            referenceKey: 'name',
            referenceQual: 'javascript: new LifeCycleUtil().filterLifeCycleStageStatus()',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        time_zone: StringColumn({
            dropdown: 'dropdown_without_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_user',
                field: 'time_zone',
            },
            label: 'Time zone',
        }),
    },
    textIndex: true,
})
